def count_primes(n):
    s = [True] * (n + 1)
    s[0] = False
    s[1] = False
    for i in range(2, int(n**0.5) + 1):
        if s[i]:
            s[i*i:n+1:i] = [False] * len(range(i*i, n+1, i))
    return sum(s)

def count_primes(n):
    if n < 2:
        return 0
    if n < 3:
        return 1
    m = (n - 1) // 2
    s = [True] * (m + 1)
    for i in range(1, int((n**0.5 - 1) / 2) + 1):
        if s[i]:
            p = 2 * i + 1
            s[2*i*(i+1):m+1:p] = [False] * len(range(2*i*(i+1), m+1, p))
    return 1 + sum(s[1:])
